function initMagazine(){
 const header=document.querySelector('.site-header'),menu=document.querySelector('.menu-toggle');menu?.addEventListener('click',()=>{const open=header?.classList.toggle('menu-open');menu.setAttribute('aria-expanded',String(Boolean(open)))});document.querySelectorAll('.mobile-menu a').forEach(a=>a.addEventListener('click',()=>header?.classList.remove('menu-open')));
 const activeCategory=document.querySelector('.magazineCategoryNavInner .active');if(activeCategory&&matchMedia('(max-width: 768px)').matches)requestAnimationFrame(()=>activeCategory.scrollIntoView({block:'nearest',inline:'center'}));
 const more=document.querySelector('[data-mag-more]'),cards=[...document.querySelectorAll('[data-mag-card]')];if(more){let shown=6;const update=()=>{cards.forEach((c,i)=>c.hidden=i>=shown);more.hidden=shown>=cards.length};update();more.addEventListener('click',()=>{shown+=6;update()})}
 const form=document.querySelector('[data-mag-search]'),results=document.querySelector('[data-search-results]'),summary=document.querySelector('[data-search-summary]'),data=window.__MAGAZINE_INDEX__||[];
 const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
 const card=p=>`<article class="mag-card"><a href="${escape(p.url||`/magazine/${p.slug}`)}">${p.heroImage?`<img src="${escape(p.heroImage)}" alt="${escape(p.heroImageAlt)}" loading="lazy" decoding="async">`:''}<div><span>${escape(p.categoryName)}</span><h3>${escape(p.title)}</h3><p>${escape(p.description)}</p>${p.updatedAt?`<small>${escape(p.updatedAt)} · ${escape(p.readingTime)}</small>`:''}</div></a></article>`;
 const emptyState='<div class="empty-state"><h2>검색 결과가 없습니다</h2><p>여행 일정, 지역, 교통, 쇼핑 카테고리에서 다시 찾아보세요.</p><a href="/magazine">전체 글 보기 →</a><a href="/areas">지역별 픽 보기 →</a><a href="/travel-prep">여행 준비 보기 →</a></div>';
 const runSearch=()=>{if(!form||!results||!summary)return;const query=new URLSearchParams(location.search).get('q')?.trim()||'';form.querySelector('input').value=query;if(!query){summary.textContent='검색어를 입력하면 제목, 요약, 카테고리와 태그에서 찾아드립니다.';results.innerHTML=emptyState;return}const terms=query.toLowerCase().split(/\s+/).filter(Boolean),found=data.filter(p=>{const hay=[p.title,p.description,p.categoryName,...p.tags].join(' ').toLowerCase();return terms.every(t=>hay.includes(t))});summary.textContent=found.length?`“${query}” 검색 결과 ${found.length}개`:`“${query}”에 해당하는 콘텐츠가 없습니다.`;results.innerHTML=found.length?found.map(card).join(''):emptyState};
 form?.addEventListener('submit',event=>{event.preventDefault();const query=form.querySelector('input').value.trim();history.replaceState({},'',query?`/magazine/search?q=${encodeURIComponent(query)}`:'/magazine/search');runSearch()});runSearch();
 document.querySelector('[data-copy-url]')?.addEventListener('click',async event=>{try{await navigator.clipboard.writeText(location.href);event.currentTarget.textContent='URL 복사 완료'}catch{event.currentTarget.textContent='복사할 수 없어요'}});
 document.querySelector('[data-mag-share]')?.addEventListener('click',async event=>{try{if(navigator.share)await navigator.share({title:document.title,url:location.href});else await navigator.clipboard.writeText(location.href);event.currentTarget.textContent='공유 완료'}catch(error){if(error?.name!=='AbortError')event.currentTarget.textContent='공유할 수 없어요'}})
}
if(typeof document!=='undefined'){if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initMagazine,{once:true});else initMagazine()}
